 function refinementHTML(w,kind){const r=refinement(w,kind),d=layout(w,kind);if(!r.open)return '';return `<section class="sa-position" aria-label="Modify graphic"><label class="sa-field">What would you change?<textarea id="saRefineBrief" rows="3" maxlength="1500" placeholder="For example: make the names larger, soften the colours, or match the lettering in our example.">${esc(r.brief)}</textarea></label><p class="sa-note">AI uses this preview${d.example_path?' and your club’s previous example':''}. Match figures stay unchanged. Uses your club’s AI allowance.</p><div class="sa-actions"><button class="btn secondary" id="saTryRefinement" ${!r.brief.trim()?'disabled':''}>Try changes</button>${d.example_path?`<button class="btn ghost" id="saMatchExample">Match our example</button>`:''}</div><p class="sa-status sa-note" id="saRefineStatus" role="status" aria-live="polite">${esc(r.message)}</p>${r.candidate&&d.badge_crops?.length?`<div style="display:flex;gap:12px;flex-wrap:wrap">${d.badge_crops.map(c=>`<figure style="margin:8px 0;max-width:160px"><canvas data-sa-badge="${esc(c.label)}" aria-label="${esc(c.label)} artwork" style="width:140px;height:80px;object-fit:contain"></canvas><figcaption class="sa-note">${c.label==='WIN'?'WIN · used for wins':'DEF · used for defeats'}</figcaption></figure>`).join('')}</div><p class="sa-note">Check that these crops contain only the correct badge before keeping this version.</p>`:''}<div class="sa-actions">${r.candidate?'<button class="btn" id="saUseRefinement" disabled>Use this version</button>':''}${r.history.length?`<button class="btn ghost" id="saUndoRefinement" ${r.saveUncertain?'disabled':''}>Undo last change</button>`:''}</div>${r.artworkBrief?`<button class="btn secondary" id="saRefineArtwork" ${r.candidate||w.designDirty[kind]?'disabled':''}>Prepare artwork change</button><p class="sa-note">${r.candidate?'Use this version first, then review the artwork change.':w.designDirty[kind]?'Save the layout first, then review the artwork change.':'Continue in the artwork editor to review this image change.'}</p>`:''}</section>`;}
