 async function saveLayout(s,kind){const w=state(s),r=await rpc(s,'save_design',{kind,revision:w.context.designs[kind]?.revision||0,layout:layout(w,kind)});w.context.designs[kind]={layout:structuredClone(layout(w,kind)),revision:r.revision};w.designDirty[kind]=false;notice(s,'Layout saved.');}
